<?php
declare(strict_types=1);
// CLI-only; outside nginx root. Never backs up PDF originals.
if(PHP_SAPI!=='cli')exit(1);
const DATA='/var/lib/read-local';const BACKUPS='/volume1/download/read-backups';
date_default_timezone_set('Asia/Shanghai');umask(0077);
function erase(string $p,string $root):void{$r=realpath($root);$target=realpath($p);if(!$r||!$target||!str_starts_with($target,$r.'/')||is_link($p))throw new RuntimeException('Unsafe cleanup path');foreach(new DirectoryIterator($p) as $item){if($item->isDot())continue;$f=$item->getPathname();if($item->isLink())throw new RuntimeException('Symlink refused');if($item->isDir())erase($f,$root);else unlink($f);}rmdir($p);}
function copyTree(string $from,string $to):void{if(!is_dir($to))mkdir($to,0700,true);foreach(new DirectoryIterator($from) as $item){if($item->isDot())continue;if($item->isLink())throw new RuntimeException('Symlink refused');$dest=$to.'/'.$item->getFilename();if($item->isDir())copyTree($item->getPathname(),$dest);elseif(!copy($item->getPathname(),$dest))throw new RuntimeException('Backup copy failed');}}
try{$mode=$argv[1]??'';$dry=in_array('--dry-run',$argv,true);if(!in_array($mode,['backup','cleanup']))throw new RuntimeException('Use backup or cleanup [--dry-run]');
$job=fopen(DATA.'/maintenance-job.lock','c');if(!flock($job,LOCK_EX|LOCK_NB))throw new RuntimeException('Another maintenance job is running');$lock=fopen(DATA.'/maintenance.lock','c');if(!flock($lock,LOCK_EX))throw new RuntimeException('Cannot lock uploads');
if($mode==='backup'){
 if(!is_dir(BACKUPS))throw new RuntimeException('Backup directory missing');$name='monthly-'.date('Ymd-His').'-'.bin2hex(random_bytes(3));$stage=BACKUPS.'/.'.$name.'.partial';mkdir($stage,0700);
 $src=new SQLite3(DATA.'/library.sqlite',SQLITE3_OPEN_READONLY);$src->busyTimeout(10000);$dest=new SQLite3($stage.'/library.sqlite');$dest->busyTimeout(10000);if(!$src->backup($dest))throw new RuntimeException('SQLite online backup failed');if($dest->querySingle('PRAGMA integrity_check')!=='ok')throw new RuntimeException('Backup integrity failed');$count=$dest->querySingle('SELECT COUNT(*) FROM books');$dest->close();$src->close();copyTree(DATA.'/covers',$stage.'/covers');file_put_contents($stage.'/manifest.json',json_encode(['format'=>'read-local-backup-v1','created'=>date(DATE_ATOM),'books'=>$count,'includes'=>['library.sqlite','covers'],'pdfIncluded'=>false],JSON_PRETTY_PRINT));rename($stage,BACKUPS.'/'.$name);flock($lock,LOCK_UN);
 $sets=[];foreach(new DirectoryIterator(BACKUPS) as $i){if($i->isDot()||$i->isLink()||!$i->isDir()||!preg_match('/^monthly-\d{8}-\d{6}-[a-f0-9]{6}$/D',$i->getFilename()))continue;$m=json_decode((string)@file_get_contents($i->getPathname().'/manifest.json'),true);if(($m['format']??'')==='read-local-backup-v1')$sets[]=$i->getPathname();}rsort($sets);foreach(array_slice($sets,5) as $old)erase($old,BACKUPS);echo 'Backup verified: '.BACKUPS.'/'.$name."\n";
}else{
 $db=new PDO('sqlite:'.DATA.'/library.sqlite');$db->setAttribute(PDO::ATTR_ERRMODE,PDO::ERRMODE_EXCEPTION);$db->exec('PRAGMA busy_timeout=10000');$removed=0;$skipped=0;
 foreach(new DirectoryIterator(DATA.'/parts') as $i){if($i->isDot())continue;if($i->isLink()||!$i->isDir()||!preg_match('/^[a-f0-9-]{36}$/D',$i->getFilename())){$skipped++;continue;}$id=$i->getFilename();$s=$db->prepare('SELECT expires FROM uploads WHERE id=?');$s->execute([$id]);$expires=$s->fetchColumn();if($expires!==false&&(int)$expires>time()){$skipped++;continue;}$latest=$i->getMTime();foreach(new RecursiveIteratorIterator(new RecursiveDirectoryIterator($i->getPathname(),FilesystemIterator::SKIP_DOTS)) as $f){if($f->isLink()){$latest=time();break;}$latest=max($latest,$f->getMTime());}if($latest>time()-86400){$skipped++;continue;}$f=fopen($i->getPathname().'/lock','c');if(!flock($f,LOCK_EX|LOCK_NB)){$skipped++;fclose($f);continue;}if(!$dry){erase($i->getPathname(),DATA.'/parts');$s=$db->prepare('DELETE FROM uploads WHERE id=? AND expires<=?');$s->execute([$id,time()]);}$removed++;fclose($f);}
 echo json_encode(['dryRun'=>$dry,'eligibleOrRemoved'=>$removed,'skipped'=>$skipped])."\n";
}
}catch(Throwable $e){fwrite(STDERR,'Maintenance failed: '.$e->getMessage()."\n");exit(1);}
